css:
.chapter-scope {
  --ink: #1a1a1a;
  --muted: #666;
  --accent: #d9531e;
  --warm: #f4f4f4;
  --line: #e0e0e0;
  --paper: #ffffff;

  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  line-height: 1.6;
  font-size: 16px;
  max-width: 1200px;
  margin: 0 auto;
}

.scope-header h2 {
  font-size: 2rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
  border-bottom: 2px solid var(--accent);
  display: inline-block;
  padding-bottom: 0.25rem;
}

.lead {
  font-size: 1.1rem;
  color: var(--muted);
  margin-bottom: 2rem;
  max-width: 800px;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: start;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
}

.narrative-col article {
  margin-bottom: 2rem;
}

.narrative-col h3 {
  font-size: 1.25rem;
  margin-top: 0;
  color: var(--ink);
}

.source-block {
  background: var(--warm);
  padding: 1rem;
  border-left: 4px solid var(--muted);
  margin-top: 1rem;
  font-size: 0.9rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.btn-source {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  padding: 0.25rem 0.5rem;
  font-size: 0.8rem;
  cursor: pointer;
  align-self: flex-start;
  font-family: inherit;
}

.btn-source:hover {
  border-color: var(--ink);
  color: var(--ink);
}

.panel-interactive {
  background: var(--warm);
  padding: 1.5rem;
  border-radius: 4px;
  border: 1px solid var(--line);
}

.panel-interactive h4 {
  margin-top: 0;
  font-size: 1.1rem;
}

.panel-desc {
  font-size: 0.9rem;
  color: var(--muted);
  margin-bottom: 1.5rem;
}

.control-group {
  margin-bottom: 1.5rem;
}

.control-group label {
  display: block;
  font-weight: bold;
  margin-bottom: 0.5rem;
  font-size: 0.9rem;
}

.control-group select {
  width: 100%;
  padding: 0.5rem;
  font-size: 1rem;
  border: 1px solid var(--line);
  background: var(--paper);
  color: var(--ink);
}

.viz-container {
  background: var(--paper);
  border: 1px solid var(--line);
  padding: 1rem;
  margin-bottom: 1rem;
  min-height: 200px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.legend {
  display: flex;
  gap: 1rem;
  font-size: 0.85rem;
  margin-top: 0.5rem;
  justify-content: center;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.data-readout {
  display: flex;
  justify-content: space-between;
  border-top: 1px solid var(--line);
  padding-top: 1rem;
  margin-top: 1rem;
}

.metric {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.metric .label {
  font-size: 0.8rem;
  color: var(--muted);
}

.metric .value {
  font-size: 1.25rem;
  font-weight: bold;
  color: var(--ink);
}

.metric .status-ok {
  color: #2e7d32;
}

.btn-reset {
  width: 100%;
  padding: 0.75rem;
  background: var(--ink);
  color: var(--paper);
  border: none;
  font-size: 0.9rem;
  cursor: pointer;
  margin-top: 1rem;
  transition: opacity 0.2s;
}

.btn-reset:hover {
  opacity: 0.9;
}

.scope-footer {
  margin-top: 3rem;
  border-top: 1px solid var(--line);
  padding-top: 1.5rem;
}

.limitations-box h5 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

.limitations-box ul {
  margin: 0;
  padding-left: 1.25rem;
  font-size: 0.9rem;
  color: var(--muted);
}
button[data-source]{background:#fff!important;color:#265976!important}

javascript:
(function() {
  'use strict';

  // Data derived from S027/S028 text descriptions
  const DATA = {
    gender: {
      dim: "保护女性 (Sparing Females)",
      groups: [
        { name: "女性 (Female)", val: 0.49, color: "var(--ink)" }, // Baseline approx
        { name: "男性 (Male)", val: 0.43, color: "var(--accent)" }  // 0.06 less inclined
      ],
      delta: 0.06
    },
    religiosity: {
      dim: "保护人类 (Sparing Humans)",
      groups: [
        { name: "低宗教性", val: 0.50, color: "var(--ink)" },
        { name: "高宗教性 (+1SD)", val: 0.59, color: "var(--accent)" } // 0.09 more inclined
      ],
      delta: 0.09
    }
  };

  const selectEl = document.getElementById('demographic-select');
  const svgEl = document.getElementById('bar-chart');
  const deltaValEl = document.getElementById('delta-val');
  const resetBtn = document.getElementById('reset-filter');

  function renderChart(key) {
    const data = DATA[key];
    if (!data) return;

    // Clear SVG
    svgEl.innerHTML = '';

    // Update Text
    deltaValEl.textContent = data.delta.toFixed(2);

    // Chart Dimensions
    const width = 400;
    const height = 200;
    const barHeight = 40;
    const gap = 30;
    const startX = 150;
    const maxVal = 1.0; // 100% probability scale
    const scale = (width - startX - 20) / maxVal;

    // Create Bars
    data.groups.forEach((group, index) => {
      const y = 40 + index * (barHeight + gap);
      const barWidth = group.val * scale;

      // Bar Rect
      const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      rect.setAttribute("x", startX);
      rect.setAttribute("y", y);
      rect.setAttribute("width", barWidth);
      rect.setAttribute("height", barHeight);
      rect.setAttribute("fill", group.color);
      rect.setAttribute("rx", 4);
      svgEl.appendChild(rect);

      // Label
      const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
      text.setAttribute("x", startX - 10);
      text.setAttribute("y", y + barHeight / 2 + 5);
      text.setAttribute("text-anchor", "end");
      text.setAttribute("font-size", "14px");
      text.setAttribute("fill", "var(--ink)");
      text.textContent = group.name;
      svgEl.appendChild(text);

      // Value Label
      const valText = document.createElementNS("http://www.w3.org/2000/svg", "text");
      valText.setAttribute("x", startX + barWidth + 5);
      valText.setAttribute("y", y + barHeight / 2 + 5);
      valText.setAttribute("font-size", "14px");
      valText.setAttribute("fill", "var(--muted)");
      valText.textContent = (group.val * 100).toFixed(0) + "%";
      svgEl.appendChild(valText);
    });

    // Axis Line
    const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
    line.setAttribute("x1", startX);
    line.setAttribute("y1", 30);
    line.setAttribute("x2", startX);
    line.setAttribute("y2", 180);
    line.setAttribute("stroke", "var(--line)");
    svgEl.appendChild(line);

    // Axis Label
    const axisLabel = document.createElementNS("http://www.w3.org/2000/svg", "text");
    axisLabel.setAttribute("x", width / 2);
    axisLabel.setAttribute("y", 195);
    axisLabel.setAttribute("text-anchor", "middle");
    axisLabel.setAttribute("font-size", "12px");
    axisLabel.setAttribute("fill", "var(--muted)");
    axisLabel.textContent = "偏好概率 (Probability of Preference)";
    svgEl.appendChild(axisLabel);
  }

  function handleInput(e) {
    renderChart(e.target.value);
  }

  function handleReset() {
    selectEl.value = "gender";
    renderChart("gender");
  }

  // Init
  selectEl.addEventListener('change', handleInput);
  resetBtn.addEventListener('click', handleReset);
  renderChart('gender');

})();
